import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.BM5YPQmL.js";const _=JSON.parse('{"title":"向导库（wizard_lib.h）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/wizard-library.md","filePath":"zh/l1/wizard-library.md"}'),i={name:"zh/l1/wizard-library.md"};function c(s,t,r,l,n,h){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="向导库-wizard-lib-h" tabindex="-1">向导库（wizard_lib.h） <a class="header-anchor" href="#向导库-wizard-lib-h" aria-label="Permalink to &quot;向导库（wizard_lib.h）&quot;">​</a></h1><p>8 个合并应用背后的共享原语。仅头文件，位于 <code>ocos/interface/wizard_lib.h</code> - 每个应用编译自己的副本 （<code>_shared</code> 风格）；逐字直通路径从不触碰它（它们保留历史的 <code>l1svc_main()</code> 语义）。</p><h2 id="交互契约" tabindex="-1">交互契约 <a class="header-anchor" href="#交互契约" aria-label="Permalink to &quot;交互契约&quot;">​</a></h2><ul><li><strong>输出缓冲</strong>：调用者持有一个 <code>WIZ_OUT_CAP</code>（32768）的 <strong>静态</strong>缓冲 - BSS，不是栈（l1svc_main 注记：用户栈上 32 KiB 是风险，BSS 每次执行都映射）。</li><li><strong>行输入</strong>：<code>SYS_READLINE</code> - 内核行编辑器、回显 + 退格、 阻塞、仅可打印 ASCII（没有 Ctrl 字符：绝不在 READLINE 提示上 承诺&quot;Ctrl+C 退出&quot;）。</li><li><strong>单键选择</strong>：<code>SYS_GETCH</code> 非阻塞轮询（ush 自旋等待模式）。 数字 1..9 选择，<code>q</code>/<code>Q</code>/ESC 中止，越界数字被忽略。</li><li><strong>字符串</strong>：每一行人类可见文本都经 <code>tr_()</code> 渲染 - 整个向导 实时跟随 <code>lang en|zh</code>。</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原语</th><th>作用</th></tr></thead><tbody><tr><td><code>wiz_svc(cat, op, arg, out)</code></td><td>运行一个 L1SVC 操作并打印其文本；失败时打印 <code>tr_(&quot;wiz_svc_failed&quot;)</code>；返回原始 rc</td></tr><tr><td><code>wiz_svc_quiet(cat, op, arg, out)</code></td><td>同样的调用，不打印 - 由调用者探测 <code>out</code></td></tr><tr><td><code>wiz_find(hay, needle)</code></td><td>子串探测（1/0）- 锚点测试</td></tr><tr><td><code>wiz_token_after(hay, key, dst, cap)</code></td><td>复制 <code>key</code> 之后的第一个词（<code>&quot;IP: 10.0.2.15&quot;</code> + <code>&quot;IP:&quot;</code> -&gt; <code>&quot;10.0.2.15&quot;</code>）；键不存在时返回 NULL</td></tr><tr><td><code>wiz_ask(prompt, buf, cap)</code></td><td>提示 + 一行 READLINE（总是 NUL 结尾；空输入 = &quot;&quot;）</td></tr><tr><td><code>wiz_confirm(what)</code></td><td>一次性 y/N - 只有裸 <code>y</code>/<code>Y</code> 算作 yes</td></tr><tr><td><code>wiz_pause()</code></td><td><code>tr_(&quot;wiz_pause&quot;)</code> + ENTER</td></tr><tr><td><code>wiz_menu(title, items, n)</code></td><td>基于可 tr_() 翻译键的编号单键菜单（1..9）；返回 1 起始的选择，q/ESC 返回 0</td></tr><tr><td><code>wiz_banner(title)</code> / <code>wiz_step(n, total, what)</code></td><td>框架行</td></tr><tr><td><code>wiz_ok(msg)</code> / <code>wiz_fail(msg)</code></td><td><code>[OK]</code> / <code>[!!]</code> 判定行</td></tr></tbody></table><h2 id="锚点纪律" tabindex="-1">锚点纪律 <a class="header-anchor" href="#锚点纪律" aria-label="Permalink to &quot;锚点纪律&quot;">​</a></h2><p>向导读的是服务自己的英文输出行 - 与脚本解析的相同行 - 绝不是 第二种&quot;结构化&quot;拼法：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wiz_svc_quiet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(L1SVC_CAT_OTA, L1SVC_OTA_UPDATE, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, out);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wiz_find</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(out, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A/B disk: present&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)) { ... }</span></span></code></pre></div><p>锚点是兼容性表面的一部分（见 <a href="./surface-map.html">surface-map.md</a>）：重命名它们会同时破坏向导、 E2E 套件和用户文档。</p><h2 id="安全模型" tabindex="-1">安全模型 <a class="header-anchor" href="#安全模型" aria-label="Permalink to &quot;安全模型&quot;">​</a></h2><ul><li>破坏性操作（<code>mkfs.*</code>、<code>abdisk</code>、<code>install</code>、<code>rm</code>、电源动作） <strong>绝不止一次按键</strong>：先问目标名，让用户重新输入一遍，再一个 裸 <code>y</code> - 三次刻意步骤。经典/直通门保持逐字（脚本保留其无 提示行为）。</li><li>数字字段（卷、睡眠秒数、chmod 模式）在触达任何服务之前先做 仅数字校验。</li><li>跨领域修复正是意义所在：<code>update</code> 向导在检查更新之前，先通过 DHCP（net 服务）修复缺失的 IP，通过 lsblk + abdisk（block 服务）修复缺失的 A/B 盘。</li></ul><h2 id="共享-i18n-键" tabindex="-1">共享 i18n 键 <a class="header-anchor" href="#共享-i18n-键" aria-label="Permalink to &quot;共享 i18n 键&quot;">​</a></h2><p>每个大应用的资源都带：<code>wiz_title</code>、<code>wiz_select</code>、<code>wiz_quit</code>、 <code>wiz_pause</code>、<code>wiz_svc_failed</code>（+ 它自己的键）。缺失的键回退到 英文，再回退到键字符串 - 向导绝不会因翻译缺口崩溃。</p>`,14)])])}const u=e(i,[["render",c]]);export{_ as __pageData,u as default};
